const a={"home.about.card.list.0":"Výskum a validácia smerovania produktu (prebieha)","home.about.card.list.1":"Rozvoj základných schopností: Inžiniersky systém / Dátové a servisné schopnosti / Infrastruktúra","home.about.card.list.2":"Prototyping a rýchla iterácia: Od nápadu po použiteľnú verziu","home.about.card.list.3":"Dodržiavanie a bezpečnosť: Dôraz na bezpečnosť údajov a ochranu súkromia","home.about.card.note":"Keďže je rozsah podnikania stále v prieskumnej fáze...","home.about.card.title":"Čo robíme?","home.about.desc.0":"Sme technologická spoločnosť zameraná na sieťové technológie, ktorá sa sústreďuje na vlastný výskum...","home.about.desc.1":"Súčasný obchodný rozsah je stále v procese neustáleho preskúmavania...","home.about.hl.0.num":"Samo-vyvinutý prvý","home.about.hl.0.text":"Neustále investovanie do vlastných produktov a podnikania.","home.about.hl.1.num":"Stála iterácia","home.about.hl.1.text":"Zdôraznite kvalitu inžinierstva, udržateľnosť a škálovateľnosť.","home.about.hl.2.num":"Nepretržite skúmanie","home.about.hl.2.text":"Dynamická evolúcia obchodných smerov postupne vytvára jasné hranice.","home.about.title":"O nás","home.brand.en":"TreeHouse Tech · Shanghai","home.common.city":"Šanghaj · ŠANGHAJ","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"Ak nás potrebujete kontaktovať, prosím, komunikujte prostredníctvom e-mailu...","home.contact.label.city":"Mesto","home.contact.label.company":"Názov spoločnosti","home.contact.label.email":"Email","home.contact.title":"Kontaktné informácie","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"O nás","home.footer.links.contact":"Kontaktujte nás","home.footer.links.home":"Domov","home.footer.slogan":"Zamerajte sa na nezávislý výskum a vývoj · Neustále skúmanie · Stabilná iterácia","home.hero.cta.about":"Zistite viac o nás →","home.hero.cta.contact":"Kontaktné informácie","home.hero.desc":"Sme technologická spoločnosť zameraná na sieťové technológie a vlastný výskum. Neustále skúmame hodnotné produktové smerovania a technické implementačné cesty, s cieľom dosiahnuť dlhodobú iteráciu a stabilné dodanie.","home.hero.glass":'Smerovanie prieskumu → Inžinierska implementácia → Zlepšovanie produktu <span class="dot"></span> Dlhodobé myslenie / Stabilné dodávanie',"home.hero.meta.0.label":"Zamerané na produkt a inžinierstvo","home.hero.meta.0.num":"Vlastný vývoj","home.hero.meta.1.label":"Nepretržité iterácie a zdokonaľovanie","home.hero.meta.1.num":"Dlhodobé","home.hero.meta.2.label":"Zvýraznite kvalitu a súlad","home.hero.meta.2.num":"Stabilný","home.hero.mini.foot":"* Aktuálna oficiálna webová stránka je základná úvodná stránka a obsah bude priebežne aktualizovaný, ako sa podnikanie vyvíja.","home.hero.mini.head":"Tip","home.hero.mini.main":"Nepretržite skúmanie obchodných smerov","home.hero.mini.stats.0.k":"Zameranie","home.hero.mini.stats.0.v":"Vlastný vyvinutý produkt","home.hero.mini.stats.1.k":"Forma","home.hero.mini.stats.1.v":"Postupne objasniť","home.hero.mini.stats.2.k":"Rytmus","home.hero.mini.stats.2.v":"Iteratívny pokrok","home.hero.mini.stats.3.k":"Cieľ","home.hero.mini.stats.3.v":"Udržateľný rast","home.hero.title":'Zameranie na <span class="accent"> nezávislý výskum a vývoj </span> a prieskum produktov',"home.html.lang":"sk","home.meta.description":"上海树下小屋网络科技有限公司 - Zamerané na nezávislé výskumy a objavovanie produktov","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"O nás","home.nav.contact":"Kontaktujte nás","home.nav.home":"Domov","home.nav.toggle":"Rozbaliť ponuku","home.noscript":"Táto stránka vyžaduje JavaScript pre kompletný interaktívny zážitok (navigačné menu, efekty posúvania atď.).","nav.apps":"Centrum aplikácií","nav.support":"Podpora","apps.hero.eyebrow":"sxxw.site · Centrum podpory aplikácií","apps.hero.title":"Každá aplikácia prichádza s jasnými pokynmi a hranicami dát, ktoré máte pod kontrolou.","apps.hero.desc":"Nájdete tu prehľady produktov, návody na začiatok, zásady ochrany súkromia, podmienky a technickú podporu. Prečítajte si časť pre platformu, ktorú skutočne používate.","apps.card.cta":"Zobraziť aplikáciu","apps.memoria.desc":"Sledujte narodeniny, výročia a odpočítavania. Verzia pre iOS podporuje voliteľnú súkromnú synchronizáciu cez iCloud; vydanie Memoria v Huawei AppGallery beží úplne v zariadení.","apps.memoria.tag":"Výročia · Pripomienky","apps.timetrails.desc":"Zaznamenávanie trás GPS s dôrazom na súkromie: automaticky zaznamenáva výlety, tréningy a cesty, kreslí vaše stopy na mape a rozsvecuje mestá, ktoré ste navštívili. Trasy zostávajú predvolene v zariadení s voliteľnou súkromnou zálohou v iCloud.","apps.timetrails.tag":"Trasy GPS · Cesty","apps.traceapp.desc":"Zaznamenáva trasu, vzdialenosť, rýchlosť a tempo. Bez účtu, bez vstavaných reklám či analytiky tretích strán.","apps.traceapp.tag":"Cesty · Štatistiky","apps.footer.slogan":"Produkty · Návody · Súkromie a podpora","support.brand":"Podpora","support.hero.eyebrow":"sxxw.site · Centrum podpory","support.hero.title":"Spojte sa s TreeHouse spôsobom, ktorý vám najviac vyhovuje.","support.hero.desc":"Všetky oficiálne kanály podpory pre aplikácie TreeHouse na jednom mieste: spätná väzba, hodnotenia v obchodoch s aplikáciami a oficiálne komunitné skupiny. Najprv lokálne, bez reklám, bez sledovania tretími stranami.","support.g1.title":"Spätná väzba","support.g1.note":"Narazili ste na problém alebo máte nápad? Ozvite sa nám ktorýmkoľvek spôsobom nižšie — čítame každú správu.","support.g1.feedback.name":"Spätná väzba v aplikácii","support.g1.feedback.desc":"Odošlite priamo v každej aplikácii; vaša verzia, zariadenie a informácie o systéme sa priložia automaticky, aby sme to preskúmali rýchlejšie.","support.g1.feedback.cta":"Zobraziť aplikácie","support.g1.email.name":"Poslať e-mail","support.g1.email.desc":"Pri formálnych žiadostiach a otázkach súkromia či účtu poskytuje e-mail podrobnejšiu odpoveď.","support.g1.email.cta":"Poslať e-mail","support.g2.title":"Ohodnoťte aplikácie (každú zvlášť)","support.g2.note":"Ak sa vám páčia, zanechajte hodnotenie v obchode, ktorý používate — vidíme ho a odpovieme. Ťuknite na ten, ktorý zodpovedá vašej aplikácii.","support.g2.cta.write":"Napísať hodnotenie","support.g2.cta.goto":"Prejsť na hodnotenie","support.g2.memoria.huawei.platform":"HarmonyOS · Zariadenia Huawei","support.g3.title":"Skupiny WeChat · QQ · Telegram","support.g3.note":"Pridajte sa k našim oficiálnym skupinám pre novinky a pomoc od ostatných používateľov: WeChat / QQ v Číne, Telegram inde.","support.g3.wechat.name":"Skupina WeChat","support.g3.wechat.desc":"Každodenná komunikácia a pomoc. Po naplnení skupiny zverejníme nový QR kód.","support.g3.qq.name":"Skupina QQ","support.g3.qq.desc":"Pre používateľov v Číne; vysoký limit členov.","support.g3.tg.name":"Skupina Telegram","support.g3.tg.desc":"Komunikácia a otázky pre medzinárodných používateľov.","support.g3.join":"Pripojiť sa","support.pending":"Čoskoro","support.foot":"Nenašli ste správny kanál? Napíšte na house@sxxw.site a ozveme sa vám.","support.footer.slogan":"Spätná väzba · Hodnotenia v obchodoch · Komunitné skupiny","mem.ios.tagline":"Zaznamenajte narodeniny, výročia a dôležité dni — nech je čas vnímaný s nehou.","mem.ios.desc":"Uložte narodeniny, výročia, výročia vzťahu, sviatky a dni, na ktorých vám záleží, na jedno pokojné miesto. Odpočítavajte, koľko dní ostáva, a počítajte nahor, koľko už uplynulo.","mem.ios.feat.0":"Narodeniny, výročia, sviatky a vlastné udalosti","mem.ios.feat.1":"Dátumy v gregoriánskom a čínskom lunárnom kalendári","mem.ios.feat.2":"Odpočítavanie, počítanie nahor a priebeh života","mem.ios.feat.3":"Lokálne pripomienky, widgety na ploche a uzamknutej obrazovke","mem.ios.feat.4":"Rýchly prehľad na Apple Watch","mem.ios.feat.5":"Voliteľná súkromná synchronizácia cez iCloud","mem.ios.guide.0.t":"Vytvorte prvý záznam","mem.ios.guide.0.b":"Po otvorení aplikácie zvoľte Pridať a vyplňte názov, dátum a poznámku, ktorú si chcete uchovať. Podľa potreby zvoľte narodeniny, výročie, sviatok alebo vlastnú udalosť.","mem.ios.guide.1.t":"Zvoľte pravidlo dátumu","mem.ios.guide.1.b":"Narodeniny a výročia môžu používať gregoriánsky alebo lunárny kalendár. Pri lunárnych záznamoch sa ďalší dátum vypočíta podľa pravidla.","mem.ios.guide.2.t":"Nastavte pripomienky","mem.ios.guide.2.b":"Zapnite lokálne upozornenia pre dôležité dni a zvoľte čas pripomienky v daný deň alebo vopred. Ak je povolenie na upozornenia vypnuté, aplikácia vás vyzve otvoriť systémové nastavenia.","mem.ios.guide.3.t":"Zapnite synchronizáciu podľa potreby","mem.ios.guide.3.b":"Na synchronizáciu medzi vlastným iPhone, iPad a Apple Watch zapnite synchronizáciu, keď ste prihlásení do iCloud. Údaje idú do vašej súkromnej databázy CloudKit; vývojári ich nedokážu čítať.","mem.hm.tagline":"Zaznamenajte narodeniny, výročia a dôležité dni lokálne v zariadení.","mem.hm.desc":"Toto je lokálna verzia Memoria pre HarmonyOS. Bez účtu, bez siete, bez synchronizácie v cloude; údaje zostávajú len v sandboxe aplikácie vo vašom zariadení.","mem.hm.feat.0":"Narodeniny, výročia, sviatky a vlastné udalosti","mem.hm.feat.1":"Dátumy v gregoriánskom a čínskom lunárnom kalendári","mem.hm.feat.2":"Odpočítavanie, počítanie nahor a priebeh života","mem.hm.feat.3":"Lokálne pripomienky","mem.hm.feat.4":"Obnova z koša a úplné odstránenie","mem.hm.feat.5":"Bez účtu, bez reklám, bez sieťových požiadaviek","mem.hm.guide.0.t":"Vytvorte nové výročie","mem.hm.guide.0.b":"Prejdite na stránku výročí, zvoľte Nové a vyplňte názov, dátum, typ a poznámku. V prípade potreby zvoľte lunárny dátum.","mem.hm.guide.1.t":"Potvrďte ďalší dátum","mem.hm.guide.1.b":"Po uložení aplikácia zobrazí ďalší dátum na základe dátumu a pravidla opakovania. Lunárne záznamy sa prepočítajú podľa príslušného pravidla.","mem.hm.guide.2.t":"Nastavte lokálnu pripomienku","mem.hm.guide.2.b":"V zázname zvoľte čas pripomienky a počet dní vopred. Pri prvom nastavení pripomienky povoľte systémové upozornenia; vypnutie povolenia ovplyvní len pripomienky, nie zaznamenávanie či prehliadanie.","mem.hm.guide.3.t":"Spravujte lokálne údaje","mem.hm.guide.3.b":"Odstránené záznamy najprv prejdú do koša, kde ich možno obnoviť alebo úplne odstrániť. Odinštalovanie aplikácie zmaže údaje v tomto zariadení; keďže neexistuje záloha v cloude, po výmene zariadenia alebo odinštalovaní ich nemožno obnoviť.","tt.tagline":"Záznam trás GPS — uchovajte prejdenú cestu vo vlastnom čase.","tt.desc":"TimeTrails je aplikácia na záznam trás GPS s dôrazom na súkromie. Automaticky zaznamenáva cesty, beh, bicyklovanie, turistiku a jazdu autom, živo zobrazuje vaše stopy na mape a rozsvecuje navštívené mestá. Bez registrácie účtu, bez reklám či sledovania tretích strán; údaje trás sú predvolene uložené len vo vašom zariadení.","tt.feat.0":"Automaticky zaznamenáva denný pohyb a vzdialenosť","tt.feat.1":"Vytvára denné súhrny trás a aktivít podľa miestneho času","tt.feat.2":"Pripomeňte si navštívené miesta cez objavovanie hmly","tt.feat.3":"Rozpoznáva typ aktivity: chôdzu, bicyklovanie, jazdu a ďalšie","tt.feat.4":"Voliteľný import fotiek na uchovanie spomienok z trasy","tt.feat.5":"Voliteľná súkromná záloha databázy iCloud a obnova pri výmene zariadenia","tt.guide.0.t":"Zvoľte povolenie polohy","tt.guide.0.b":"Pre nepretržitý záznam na pozadí povoľte v systémovej výzve polohu „Vždy“ a „Presnú polohu“. Kedykoľvek to môžete upraviť v systémových nastaveniach.","tt.guide.1.t":"Začnite záznam","tt.guide.1.b":"Pri prvom vstupe zapnite záznam. V aplikácii môžete kedykoľvek pozastaviť alebo pokračovať — kontrola je vo vašich rukách.","tt.guide.2.t":"Pozrite si denné trasy","tt.guide.2.b":"V kalendári alebo na mape si prezrite trasu, vzdialenosť, zastávky a súhrn aktivít každého dňa.","tt.guide.3.t":"Zapnite zálohu podľa potreby","tt.guide.3.b":"Ak potrebujete obnovu pri výmene zariadenia alebo synchronizáciu viacerých zariadení, sami zapnite zálohu údajov iCloud v nastaveniach; predvolene je vypnutá.","trace.tagline":"Zaznamenajte každú cestu a kontrolu si nechajte pri sebe.","trace.desc":"TraceApp vám pomáha zaznamenať trasu, vzdialenosť, rýchlosť a tempo a ukladá údaje predovšetkým lokálne. Bez účtu, bez zabudovaných analytických či reklamných SDK tretích strán.","trace.feat.0":"Zaznamenajte a zobrazte trasu cesty","trace.feat.1":"Štatistiky vzdialenosti, rýchlosti a tempa","trace.feat.2":"Prehrávanie trasy a vizualizácia na mape","trace.feat.3":"Voliteľné rozpoznávanie stavu pohybu","trace.feat.4":"Uchováva históriu v sandboxe zariadenia","trace.feat.5":"Voliteľná synchronizácia iCloud medzi zariadeniami","trace.guide.0.t":"Udeľte povolenie polohy","trace.guide.0.b":"Pri prvom použití zvoľte podľa potreby povolenie polohy „Počas používania aplikácie“ alebo „Vždy“; povolenie možno kedykoľvek zmeniť v systémových nastaveniach.","trace.guide.1.t":"Začnite cestu","trace.guide.1.b":"Spustite záznam v aplikácii; trasa, vzdialenosť, rýchlosť a tempo sa uložia do aktuálneho zariadenia.","trace.guide.2.t":"Prehrajte a usporiadajte","trace.guide.2.b":"V histórii si pozrite trasu a štatistiky, odstráňte nepotrebné záznamy alebo exportujte cez systémové zdieľanie (ak to aplikácia ponúka).","trace.guide.3.t":"Zapnite iCloud podľa potreby","trace.guide.3.b":"Na synchronizáciu medzi vlastnými zariadeniami sami zapnite iCloud v systéme a aplikácii; vývojár nezíska vaše prihlasovacie údaje ani obsah iCloud.","app.tab.overview":"Predstavenie produktu","app.tab.start":"Úvodný sprievodca","app.tab.privacy":"Zásady ochrany súkromia","app.tab.terms":"Podmienky používania","app.tab.support":"Technická podpora","app.cta.start":"Začať","app.cta.readPrivacy":"Prečítať zásady ochrany súkromia","app.shots":"Snímky z obchodu","app.faq":"Časté otázky","app.contactTitle":"Kontaktujte nás","app.contactQ":"Ak máte otázky, kontaktujte nás:","app.supportContact":"Stále potrebujete pomoc? Napíšte na {email}.","app.getInStore":"Získať {app} v {store}","app.legal.effective":"Dátum účinnosti","app.legal.platform":"Podporovaná platforma","app.legal.appname":"Názov aplikácie","app.footerSlogan":"Predstavenie produktu · Úvodný sprievodca · Súkromie a podpora","tt.ui.headerSub":"Záznam trasy GPS · Prehľad trás · Súkromie na prvom mieste","tt.ui.ovTitle":"Prepojte čas a miesto do vlastného príbehu","tt.ui.privTitle":"Záznamy patria vám, dáta tiež","tt.ui.privBody":"Bez účtu, bez reklám či sledovania tretími stranami. Trasy zostávajú predvolene v zariadení; záloha na iCloud je úplne voliteľná a putuje len do vašej súkromnej databázy Apple CloudKit.","tt.ui.guideTitle":"Začnite prvou trasou","tt.ui.galleryTitle":"Objavte TimeTrails cez trasy každého dňa","tt.ui.desc.start":"Začnite rýchlo – od povolenia polohy až po zobrazenie denných trás.","tt.ui.desc.privacy":"Zistite, ako sa v tejto aplikácii spracúva poloha, pohyb a záloha na iCloud.","tt.ui.desc.terms":"Pred použitím tejto aplikácie si prečítajte podmienky používania.","tt.ui.desc.support":"Pomôže vám bez problémov zaznamenať a prezrieť si každú cestu.","tt.ui.faq.0.q":"Sleduje ma TimeTrails neustále?","tt.ui.faq.0.a":"Záznam ovládate vy a môžete ho kedykoľvek pozastaviť. Poloha systému sa používa len na lokálny záznam trás a dáta zostávajú predvolene v zariadení.","tt.ui.faq.1.q":"Poloha sa nezaznamenáva?","tt.ui.faq.1.a":"V ponuke «Nastavenia → Súkromie a zabezpečenie → Lokalizačné služby» vyberte pre TimeTrails možnosť «Vždy» a zapnite «Presná poloha» a obnovovanie aplikácií na pozadí.","tt.ui.faq.2.q":"Ako obnoviť zálohu z iCloudu?","tt.ui.faq.2.a":"S rovnakým Apple ID, zapnutým iCloudom a bežným pripojením môžete obnoviť alebo manuálne synchronizovať v «Záloha dát iCloud» v nastaveniach.","tt.ui.faq.3.q":"Ako úplne vymazať dáta?","tt.ui.faq.3.a":"Lokálne dáta môžete vymazať v nastaveniach aplikácie; ak je zapnutá záloha na iCloud, odstráňte aj kópiu v cloude.","trace.ui.headerSub":"Záznam trás · Dáta pod kontrolou","trace.ui.ovTitle":"Nech má každá cesta svoju stopu","trace.ui.privTitle":"Lokálne na prvom mieste, dáta pod kontrolou","trace.ui.privBody":"Bez účtu, bez vstavaných reklám či štatistík tretích strán. Trasy zostávajú predvolene v aktuálnom zariadení; synchronizácia s iCloudom sa použije, len keď ju sami zapnete.","trace.ui.guideTitle":"Začnite prvou cestou","trace.ui.galleryTitle":"Trasy, mapa a história","trace.ui.desc.start":"Začnite rýchlo – od povolenia polohy až po prezeranie trás.","trace.ui.desc.privacy":"Zistite, ako sa spracúvajú dáta o trasách, iCloud a systémové povolenia.","trace.ui.desc.terms":"Pred použitím tejto aplikácie si prečítajte podmienky používania.","trace.ui.desc.support":"Pomôže vám bez problémov zaznamenať a spravovať každú cestu.","trace.ui.faq.0.q":"Ako upraviť povolenie polohy?","trace.ui.faq.0.a":"V ponuke «Nastavenia → Súkromie a zabezpečenie → Lokalizačné služby → TraceApp» vyberte «Pri používaní aplikácie» alebo «Vždy»; kedykoľvek to môžete vypnúť.","trace.ui.faq.1.q":"Ako vymazať dáta?","trace.ui.faq.1.a":"V aplikácii môžete vymazať jednotlivé alebo všetky záznamy; odinštalovanie vymaže lokálne dáta. Ak je iCloud zapnutý, synchronizovanú kópiu treba spravovať samostatne v iCloude.","trace.ui.faq.2.q":"Čo mám priložiť pri nahlásení problému?","trace.ui.faq.2.a":"Odporúčame priložiť kroky na zopakovanie, očakávaný a skutočný výsledok, model zariadenia a verziu systému; môžete pridať snímky obrazovky, ktoré pomôžu problém lokalizovať.","mem.ui.headerSub":"Výročia · Narodeniny · Odpočítavanie","mem.ui.ovTitle":"Vytvorené na zaznamenanie všetkého dôležitého","mem.ui.privTitle":"Súkromie pred pohodlím","mem.ui.priv.ios":"Bez účtu, bez reklám, bez sledovania tretími stranami; ak je synchronizácia zapnutá, putuje len do vašej súkromnej databázy iCloud.","mem.ui.priv.hm":"Bez účtu, bez pripojenia k sieti, bez zálohy v cloude; vaše záznamy zostávajú len v aktuálnom zariadení.","mem.ui.guideTitle":"Začnite prvým záznamom","mem.ui.galleryTitle":"Pozrite si skutočné rozhranie {app}","mem.ui.storeHint":"Vyhľadajte «{app}» v {store} a získajte túto aplikáciu.","mem.ui.desc.start":"Začnite {app} používať rýchlo – od prvého vytvorenia až po povolenie upozornení.","mem.ui.desc.privacy":"Prečítajte si zásady ochrany súkromia {app} platné pre platformu, ktorú používate.","mem.ui.desc.terms":"Pred použitím {app} si prečítajte tieto podmienky používania.","mem.ui.desc.support":"Pomôže vám {app} bez problémov používať.","mem.ui.faq.0.q":"Synchronizujú sa dáta s inými zariadeniami?","mem.ui.faq.0.a.ios":"Po prihlásení do iCloudu a zapnutí synchronizácie sa dáta synchronizujú medzi iPhone, iPad a Apple Watch cez vašu súkromnú databázu iCloud.","mem.ui.faq.0.a.hm":"Nie. Táto verzia sa nepripája k sieti a neponúka synchronizáciu v cloude; dáta zostávajú len v aktuálnom zariadení.","mem.ui.faq.1.q":"Ako vymazať dáta?","mem.ui.faq.1.a.ios":"Záznamy môžete vymazať v aplikácii; odinštalovanie vymaže lokálne dáta a dáta iCloud môžete spravovať v «Nastavenia → iCloud».","mem.ui.faq.1.a.hm":"Záznamy môžete vymazať v aplikácii a vyprázdniť kôš; odinštalovanie vymaže všetky lokálne dáta.","mem.ui.faq.2.q":"Čo robiť, ak sa pripomienka nezobrazí?","mem.ui.faq.2.a":"Skontrolujte, či má záznam nastavenú pripomienku, a v systémových nastaveniach povoľte aplikácii odosielať upozornenia. Vypnutie upozornení ovplyvní len pripomienky, nie samotné záznamy.","mem.ui.pc.title":"Uchovajte dôležité dni v zariadení, ktoré vám vyhovuje.","mem.ui.pc.desc":"Vyberte platformu, ktorú používate. Obe verzie stavajú na lokálnych dátach a absencii sledovania tretími stranami, líšia sa však v synchronizácii, názve aplikácie a platných podmienkach.","mem.ui.pc.ios.desc":"Podporuje lokálne pripomienky, widgety, Apple Watch a voliteľnú súkromnú synchronizáciu cez iCloud.","mem.ui.pc.ios.cta":"Zobraziť verziu pre iOS","mem.ui.pc.hm.desc":"Úplne lokálna verzia: bez siete, bez synchronizácie v cloude; dáta zostávajú len v sandboxe aplikácie v zariadení.","mem.ui.pc.hm.cta":"Zobraziť verziu pre HarmonyOS"};export{a as default};
